29	/** Stroke colour for the links between nodes. */
30	const LINK_STROKE = '#555';
31	/** Stroke opacity for the links. */
32	const LINK_STROKE_OPACITY = 0.4;
33	/** Stroke width for the links. */
34	const LINK_STROKE_WIDTH = 1.5;
35	/** Diameter of mugshot images in pixels. */
36	const MUGSHOT_SIZE = 20;
37	/** Minimum gap between adjacent mugshot edges, in tree coordinate pixels. */
38	const MUGSHOT_GAP = 4;
39	/** Minimum SVG height in pixels. */
40	const MIN_HEIGHT = 300;
41	/**
42	 * The floor radius passed to computeTreeRadius is (width − padding) / 2 so
43	 * sparse trees still fill most of the viewport. The padding reserves space for
44	 * two mugshot radii on each side of the centred tree.
45	 */
46	const RADIUS_FLOOR_PADDING = MUGSHOT_SIZE * 4;
47	/**
48	 * Hard cap on the computed radius, expressed as a multiple of the container
49	 * width. computeTreeRadius returns Infinity when two nodes share an angle
50	 * (zero angular gap — unsatisfiable constraint). Without this cap the
51	 * subsequent `d.y *= radius` would compute 0 × Infinity = NaN for the root
52	 * node and propagate NaN into every transform attribute.
53	 */
54	const RADIUS_MAX_MULTIPLIER = 4;
55	
56	/**
57	 * A D3 radial tidy-tree visualising how players were introduced to the club.
58	 * The founding player sits at the centre and each generation fans out in
59	 * concentric rings. Because a tree is always planar, the radial layout
60	 * algorithm guarantees that no two links cross.
61	 *
62	 * The outer radius is computed in two passes: first the tree is laid out with
63	 * a unit radius to obtain the actual angular positions, then the minimum radius
64	 * that prevents any two adjacent mugshots from overlapping is derived from
65	 * those real positions and the y-coordinates are scaled accordingly. This is
66	 * exact — the naïve approach of dividing the node count at each depth by 2π
67	 * underestimates the required radius because the tidy-tree algorithm packs
68	 * nodes within subtree wedges, not uniformly around the full circle.
69	 *
70	 * The initial zoom scales the result to fill the available viewport height.
71	 * Hovering shows the player name in a tooltip; click to open their profile.
72	 * The chart is zoomable and pannable.
73	 *
74	 * @see https://observablehq.com/@d3/radial-tree/2
75	 */
76	export const FamilyTree = ({ data }: Props) => {
77	    const router = useRouter();
78	    const containerRef = useRef<HTMLDivElement>(null);
79	    const svgRef = useRef<SVGSVGElement>(null);
80	    /** Currently hovered node position + name for the Mantine Tooltip. */
81	    const [tooltip, setTooltip] = useState<{
82	        x: number;
83	        y: number;
84	        name: string;
85	    } | null>(null);
86	    /** Measured container width; drives SVG sizing. */
87	    const [width, setWidth] = useState(928);
88	    /** Measured container height; drives SVG sizing. */
89	    const [height, setHeight] = useState(600);
90	
91	    /** Update the measured dimensions whenever the container resizes. */
92	    const updateSize = useCallback(() => {
93	        if (containerRef.current) {
94	            setWidth(containerRef.current.clientWidth);
95	            setHeight(containerRef.current.clientHeight);
96	        }
97	    }, []);
98	
99	    useEffect(() => {
100	        updateSize();
101	        const ro = new ResizeObserver(updateSize);
102	        /* v8 ignore next -- containerRef.current is always set after mount; null branch is unreachable */
103	        if (containerRef.current) ro.observe(containerRef.current);
104	        return () => ro.disconnect();
105	    }, [updateSize]);
106	
107	    useEffect(() => {
108	        /* c8 ignore next — both refs are always attached before effects run; the null check is a defensive guard only */
109	        if (!svgRef.current || !containerRef.current) return;
110	
111	        const hierarchyRoot = hierarchy(data).sort((a, b) =>
112	            ascending(a.data.name, b.data.name),
113	        );
114	
115	        const maxDepth = hierarchyRoot.height;
116	
117	        /*
118	         * Pass 1 — lay out with outerRadius = 1 so every node's x is its
119	         * final angle in [0, 2π] and y is its normalised depth (depth/maxDepth).
120	         * The x-coordinates are independent of the radius and will not change
121	         * when we re-scale y in Pass 2.
122	         */
123	        const treeLayout = tree<FamilyTreeNodeType>()
124	            .size([2 * Math.PI, 1])
125	            .separation(
126	                (a, b) =>
127	                    (a.parent === b.parent ? 1 : 2) / Math.max(1, a.depth),
128	            );
129	
130	        const root = treeLayout(hierarchyRoot);
131	
132	        /*
133	         * Pass 2 — derive the smallest outer radius that prevents mugshot
134	         * overlap at every depth, floored at half the SVG width so sparse
135	         * trees still fill the space. See familyTreeRadius.ts for the maths.
136	         *
137	         * computeTreeRadius returns Infinity when two nodes share an angle
138	         * (unsatisfiable constraint). Cap at 4× the container width so that
139	         * the subsequent y-scaling never produces NaN (Infinity × 0).
140	         */
141	        const radius = Math.min(
142	            computeTreeRadius(
143	                groups(root.descendants(), (d) => d.depth),
144	                maxDepth,
145	                Math.max(0, (width - RADIUS_FLOOR_PADDING) / 2),
146	                MUGSHOT_SIZE,
147	                MUGSHOT_GAP,
148	            ),
149	            width * RADIUS_MAX_MULTIPLIER,
150	        );
151	
152	        /* Scale y-coordinates from [0, 1] to [0, radius]. */
153	        root.each((d) => {
154	            d.y *= radius;
155	        });
156	
157	        const availableHeight = Math.max(MIN_HEIGHT, height);
158	
159	        const svg = select(svgRef.current);
160	        svg.selectAll('*').remove();
161	
162	        svg.attr('width', width)
163	            .attr('height', availableHeight)
164	            .style('user-select', 'none');
165	
166	        /* All content lives in this group; zoom transforms it as a unit. */
167	        const g = svg.append('g');
168	
169	        const zoomBehaviour = zoom<SVGSVGElement, unknown>()
170	            .scaleExtent([0.1, 4])
171	            .on('zoom', (event: D3ZoomEvent<SVGSVGElement, unknown>) => {
172	                g.attr('transform', event.transform.toString());
173	            });
174	
175	        svg.call(zoomBehaviour);
176	
177	        /* Defs: circular clip path for mugshots */
178	        const defs = svg.append('defs');
179	        defs.append('clipPath')
180	            .attr('id', 'mugshot-clip')
181	            .append('circle')
182	            .attr('r', MUGSHOT_SIZE / 2)
183	            .attr('cx', 0)
184	            .attr('cy', 0);
185	
186	        /* Links */
187	        g.append('g')
188	            .attr('fill', 'none')
189	            .attr('stroke', LINK_STROKE)
190	            .attr('stroke-opacity', LINK_STROKE_OPACITY)
191	            .attr('stroke-width', LINK_STROKE_WIDTH)
192	            .selectAll('path')
193	            .data(root.links())
194	            .join('path')
195	            .attr(
196	                'd',
197	                linkRadial<
198	                    HierarchyPointLink<FamilyTreeNodeType>,
199	                    HierarchyPointNode<FamilyTreeNodeType>
200	                >()
201	                    .angle((d) => d.x)
202	                    .radius((d) => d.y),
203	            );
204	
205	        /* Nodes */
206	        const node = g
207	            .append('g')
208	            .selectAll<SVGGElement, HierarchyPointNode<FamilyTreeNodeType>>('g')
209	            .data(root.descendants())
210	            .join('g')
211	            .attr(
212	                'transform',
213	                (d) =>
214	                    `rotate(${(d.x * 180) / Math.PI - 90}) translate(${d.y},0)`,
215	            )
216	            .style('cursor', 'pointer');
217	
218	        /* Counter-rotated group so mugshots stay upright regardless of angle. */
219	        const playerG = node
220	            .append('g')
221	            .attr('transform', (d) => `rotate(${90 - (d.x * 180) / Math.PI})`);
222	
223	        playerG
224	            .append('image')
225	            .attr('href', (d) => `/api/footy/player/${d.data.id}/mugshot`)
226	            .attr('x', -MUGSHOT_SIZE / 2)
227	            .attr('y', -MUGSHOT_SIZE / 2)
228	            .attr('width', MUGSHOT_SIZE)
229	            .attr('height', MUGSHOT_SIZE)
230	            .attr('clip-path', 'url(#mugshot-clip)')
231	            .attr('preserveAspectRatio', 'xMidYMid slice');
232	
233	        /* Thin border ring around each mugshot for clarity */
234	        playerG
235	            .append('circle')
236	            .attr('r', MUGSHOT_SIZE / 2)
237	            .attr('fill', 'none')
238	            .attr('stroke', '#ccc')
239	            .attr('stroke-width', 1);
240	
241	        /*
242	         * Fit the zoom to the actual rendered content rather than an assumed
243	         * circle diameter. Trees are rarely perfectly circular — branches
244	         * cluster in sectors — so getBBox() on the content group gives the
245	         * true bounds and produces a tighter, fuller fit.
246	         */
247	        const gNode = g.node();
248	        /* c8 ignore next — svg.append('g') always returns a non-null element; unreachable via D3's API */
249	        if (gNode) {
250	            const b = gNode.getBBox();
251	            if (b.width > 0 && b.height > 0) {
252	                const pad = MUGSHOT_SIZE;
253	                const scale = Math.max(
254	                    0.1,
255	                    Math.min(
256	                        4,
257	                        (width - 2 * pad) / b.width,
258	                        (availableHeight - 2 * pad) / b.height,
259	                    ),
260	                );
261	                const tx = (width - b.width * scale) / 2 - b.x * scale;
262	                const ty =
263	                    (availableHeight - b.height * scale) / 2 - b.y * scale;
264	                svg.call(
265	                    zoomBehaviour.transform,
266	                    zoomIdentity.translate(tx, ty).scale(scale),
267	                );
268	            }
269	        }
270	
271	        /* Hover + click behaviour */
272	        node.on('mouseenter', (event: MouseEvent, d) => {
273	            const rect = svgRef.current!.getBoundingClientRect();
274	            setTooltip({
275	                x: event.clientX - rect.left,
276	                y: event.clientY - rect.top,
277	                name: d.data.name,
278	            });
279	        })
280	            .on('mouseleave', () => setTooltip(null))
281	            .on('click', (_event, d) => {
282	                router.push(`/footy/player/${d.data.id}`);
283	            });
284	    }, [data, width, height, router]);
285	
286	    return (
287	        <Paper
288	            ref={containerRef}
289	            pos="relative"
290	            data-testid="family-tree"
291	            w="100%"
292	            h="70vh"
293	            style={{ overflow: 'hidden' }}
294	        >
295	            <svg ref={svgRef} />
296	            {tooltip ? (
297	                <Tooltip
298	                    label={tooltip.name}
299	                    opened
300	                    withArrow
301	                >
302	                    <Box
303	                        pos="absolute"
304	                        left={tooltip.x}
305	                        top={tooltip.y}
306	                        w={1}
307	                        h={1}
308	                        pe="none"
309	                    />
310	                </Tooltip>
311	            ) : null}
312	        </Paper>
313	    );
314	};
